//! RFC 9380's own vectors for the statement's hash to G2: `expand_message_xmd` with SHA-256 (appendix K.1) and
//! `BLS12381G2_XMD:SHA-256_SSWU_RO_` (appendix J.10.1), the beacon chain's suite under the RFC's test DST. They pin
//! `bls::hash_to_g2`, which the statement composes itself so that it is the same code under SP1 and RISC Zero.

use group::Curve;
use xindex_finality::bls::{expand_message_xmd, hash_to_g2};

fn h(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

const EXPANDER_DST: &[u8] = b"QUUX-V01-CS02-with-expander-SHA256-128";
const SUITE_DST: &[u8] = b"QUUX-V01-CS02-with-BLS12381G2_XMD:SHA-256_SSWU_RO_";

#[test]
fn expand_message_xmd_matches_the_rfc() {
    let short: [(&str, &str); 5] = [
        ("", "68a985b87eb6b46952128911f2a4412bbc302a9d759667f87f7a21d803f07235"),
        ("abc", "d8ccab23b5985ccea865c6c97b6e5b8350e794e603b4b97902f53a8a0d605615"),
        ("abcdef0123456789", "eff31487c770a893cfb36f912fbfcbff40d5661771ca4b2cb4eafe524333f5c1"),
        ("q128_qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq", "b23a1d2b4d97b2ef7785562a7e8bac7eed54ed6e97e29aa51bfe3f12ddad1ff9"),
        ("a512_", "4623227bcc01293b8c130bf771da8c298dede7383243dc0993d2d94823958c4c"),
    ];
    for (msg, uniform) in short {
        assert_eq!(
            expand_message_xmd::<32>(msg.as_bytes(), EXPANDER_DST).to_vec(),
            h(uniform),
            "{msg}, 32 bytes"
        );
    }
    let long: [(&str, &str); 5] = [
        ("", "af84c27ccfd45d41914fdff5df25293e221afc53d8ad2ac06d5e3e29485dadbee0d121587713a3e0dd4d5e69e93eb7cd4f5df4cd103e188cf60cb02edc3edf18eda8576c412b18ffb658e3dd6ec849469b979d444cf7b26911a08e63cf31f9dcc541708d3491184472c2c29bb749d4286b004ceb5ee6b9a7fa5b646c993f0ced"),
        ("abc", "abba86a6129e366fc877aab32fc4ffc70120d8996c88aee2fe4b32d6c7b6437a647e6c3163d40b76a73cf6a5674ef1d890f95b664ee0afa5359a5c4e07985635bbecbac65d747d3d2da7ec2b8221b17b0ca9dc8a1ac1c07ea6a1e60583e2cb00058e77b7b72a298425cd1b941ad4ec65e8afc50303a22c0f99b0509b4c895f40"),
        ("abcdef0123456789", "ef904a29bffc4cf9ee82832451c946ac3c8f8058ae97d8d629831a74c6572bd9ebd0df635cd1f208e2038e760c4994984ce73f0d55ea9f22af83ba4734569d4bc95e18350f740c07eef653cbb9f87910d833751825f0ebefa1abe5420bb52be14cf489b37fe1a72f7de2d10be453b2c9d9eb20c7e3f6edc5a60629178d9478df"),
        ("q128_qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq", "80be107d0884f0d881bb460322f0443d38bd222db8bd0b0a5312a6fedb49c1bbd88fd75d8b9a09486c60123dfa1d73c1cc3169761b17476d3c6b7cbbd727acd0e2c942f4dd96ae3da5de368d26b32286e32de7e5a8cb2949f866a0b80c58116b29fa7fabb3ea7d520ee603e0c25bcaf0b9a5e92ec6a1fe4e0391d1cdbce8c68a"),
        ("a512_", "546aff5444b5b79aa6148bd81728704c32decb73a3ba76e9e75885cad9def1d06d6792f8a7d12794e90efed817d96920d728896a4510864370c207f99bd4a608ea121700ef01ed879745ee3e4ceef777eda6d9e5e38b90c86ea6fb0b36504ba4a45d22e86f6db5dd43d98a294bebb9125d5b794e9d2a81181066eb954966a487"),
    ];
    for (msg, uniform) in long {
        assert_eq!(
            expand_message_xmd::<128>(msg.as_bytes(), EXPANDER_DST).to_vec(),
            h(uniform),
            "{msg}, 128 bytes"
        );
    }
}

/// Each point as `to_uncompressed` writes it: x's imaginary then real part, then y's, as the RFC's `P.x = c0 + I * c1`
/// reads in reverse.
#[test]
fn hash_to_g2_matches_the_rfc() {
    let points: [(&str, &str); 5] = [
        ("", ""),
        ("abc", ""),
        ("abcdef0123456789", ""),
        ("q128_qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq", ""),
        ("a512_", ""),
    ];
    for (msg, point) in points {
        let p = hash_to_g2(msg.as_bytes(), SUITE_DST).to_affine();
        assert_eq!(p.to_uncompressed().to_vec(), h(point), "{msg}");
    }
}
